const rows = $input.all().map(i => i.json);

const pending = rows.filter(r =>
  String(r.STATUS_APROVAÇÃO || '').trim().toUpperCase() === 'PENDENTE' &&
  String(r.PLAN_STATUS || '').trim().toUpperCase() === 'AI_PLANNED'
);

if (pending.length === 0) {
  return [{
    json: {
      no_work: true,
      approval_queue_count: 0,
      message: 'Nenhum conteúdo AI_PLANNED está pendente de aprovação.'
    }
  }];
}

pending.sort((a, b) => {
  const p = {ALTA: 1, 'MÉDIA': 2, MEDIA: 2, BAIXA: 3};
  const pa = p[String(a.PRIORIDADE || '').toUpperCase()] || 9;
  const pb = p[String(b.PRIORIDADE || '').toUpperCase()] || 9;
  if (pa !== pb) return pa - pb;
  return Number(a.ORDEM_EDITORIAL || 999) - Number(b.ORDEM_EDITORIAL || 999);
});

return pending.map((r, idx) => ({
  json: {
    no_work: false,
    queue_position: idx + 1,
    ID_CONTEÚDO: r.ID_CONTEÚDO,
    ID_PROJETO: r.ID_PROJETO,
    TÍTULO_INTERNO: r.TÍTULO_INTERNO,
    FORMATO: r.FORMATO,
    OBJETIVO: r.OBJETIVO,
    PRIORIDADE: r.PRIORIDADE,
    BRUTOS_USADOS: r.BRUTOS_USADOS,
    HOOK: r.HOOK,
    ROTEIRO: r.ROTEIRO,
    LEGENDA: r.LEGENDA,
    CTA: r.CTA,
    TEMPLATE_ID: r.TEMPLATE_ID,
    STATUS_EDIÇÃO: r.STATUS_EDIÇÃO,
    STATUS_APROVAÇÃO: r.STATUS_APROVAÇÃO,
    PLAN_RUN_ID: r.PLAN_RUN_ID,
    CURATION_RUN_ID: r.CURATION_RUN_ID,
    approval_options: ['APROVADO', 'REVISAR', 'DESCARTADO']
  }
}));

const items = $input.all().map(i => i.json);

if (items.length === 1 && items[0].no_work === true) {
  return [{json:{
    dry_run: true,
    queue_empty: true,
    approval_queue_count: 0,
    message: items[0].message
  }}];
}

const byFormat = {};
const byProject = {};

for (const x of items) {
  const f = x.FORMATO || 'UNKNOWN';
  const p = x.ID_PROJETO || 'NO_PROJECT';
  byFormat[f] = (byFormat[f] || 0) + 1;
  byProject[p] = (byProject[p] || 0) + 1;
}

return [{
  json: {
    dry_run: true,
    queue_empty: false,
    approval_queue_count: items.length,
    by_format: byFormat,
    by_project: byProject,
    content_ids: items.map(x => x.ID_CONTEÚDO),
    approval_options: ['APROVADO', 'REVISAR', 'DESCARTADO'],
    queue: items
  }
}];
